import os
import glob

def extract_emails_from_logs(log_dir):
    emails = set()
    for log_file in glob.glob(os.path.join(log_dir, '*.log')):
        with open(log_file, 'r') as f:
            for line in f:
                try:
                    # Parse each line as JSON
                    entry = eval(line.strip())
                    if 'email' in entry:
                        emails.add(entry['email'])
                except:
                    pass
    return emails

if __name__ == '__main__':
    log_directory = './api_logs'
    results = extract_emails_from_logs(log_directory)
    print(f'Extracted {len(results)} unique emails')
    for email in sorted(results):
        print(email)
